  `nama_produk` varchar(100) NOT NULL,
  `deskripsi` text DEFAULT NULL,
  `manfaat_produk` text NOT NULL,
  `komposisi_produk` text NOT NULL,
  `harga_produk` decimal(10,2) NOT NULL,
