  `gambar_dua` longblob DEFAULT NULL,
  `gambar_tiga` longblob DEFAULT NULL,
  `kategori` enum('Perawatan Kecantikan dan Tubuh','Reproduksi Wanita','Vitalitas Pria','Kesehatan Pencernaan','Kesehatan Umum & Imunitas','Kesehatan Tulang & Sendi','Kesehatan Anak','Kesehatan Lansia','Kesehatan Mata','Kesehatan Jantung','Kesehatan Mental & Relaksasi') NOT NULL,
  `sub_kategori` enum('Jamu Cair','Jamu Bubuk','Lainnya','Kapsul','Lulur','Minyak Herbal','Minuman Instant','Balsem','Madu Herbal','Minuman Bubuk','Minuman Tradisional','Sabun Herbal','Serum','Toner','Pil Herbal','Minuman Herbal','Teh Herbal','Bubuk Herbal','Sirup Herbal','Permen Herbal','Inhaler','Krim','Patch','Suplemen','Vitamin Gummy','Tetes Mata','Aromaterapi') NOT NULL,
  `paper_type` varchar(50) NOT NULL DEFAULT 'artpaper_120',
